/**
 * countryMasks.ts
 * Country grid masks generated by rasterizing simplified border polygons
 * onto a 25×20 grid using ray casting.
 *
 * Grid convention:
 *   col 0 = west edge (minLng), col 24 = east edge (maxLng)
 *   row 0 = NORTH edge (maxLat), row 19 = south edge (minLat)
 */

export interface CountryBBox {
  minLat: number;
  maxLat: number;
  minLng: number;
  maxLng: number;
}

export interface CountryGrid {
  id: string;
  name: string;
  bbox: CountryBBox;
  cols: number;
  rows: number;
  mask: Set<string>; // "col,row"
}

// ─── Mask builder from row spans ──────────────────────────────────────────────
// Each entry: [row, start1, end1, start2, end2, ...]
type RowSpans = number[][];

function buildMask(spans: RowSpans): Set<string> {
  const s = new Set<string>();
  for (const entry of spans) {
    const row = entry[0];
    for (let i = 1; i < entry.length; i += 2) {
      const start = entry[i];
      const end   = entry[i + 1];
      for (let col = start; col <= end; col++) {
        s.add(`${col},${row}`);
      }
    }
  }
  return s;
}

