/**
 * Convert lat/lng to grid (col, row).
 * Returns null if outside bbox or outside country mask.
 */
export function latLngToCell(
  lat: number,
  lng: number,
  grid: CountryGrid
): { col: number; row: number } | null {
  const { bbox, cols, rows, mask } = grid;

  if (lat < bbox.minLat || lat > bbox.maxLat || lng < bbox.minLng || lng > bbox.maxLng) {
    return null;
  }

  const col = Math.min(cols - 1, Math.floor(((lng - bbox.minLng) / (bbox.maxLng - bbox.minLng)) * cols));
  const row = Math.min(rows - 1, Math.floor(((bbox.maxLat - lat)  / (bbox.maxLat - bbox.minLat)) * rows));

  // Return cell even if not in mask — caller decides whether to render
  return { col, row };
}

/**
 * Check if a cell is inside the country mask.
 */
export function isInMask(col: number, row: number, grid: CountryGrid): boolean {
  return grid.mask.has(`${col},${row}`);
}
